Task: `debounce` drops the final call when invoked repeatedly; the trailing invocation must fire with the latest arguments after `wait` ms.

Diff:
--- a/src/debounce.ts
+++ b/src/debounce.ts
@@ -1,13 +1,11 @@
 export function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number) {
   let timer: ReturnType<typeof setTimeout> | undefined;
-  let pending = false;
   return (...args: A) => {
-    if (pending) return;
-    pending = true;
+    if (timer !== undefined) clearTimeout(timer);
     timer = setTimeout(() => {
-      pending = false;
+      timer = undefined;
       fn(...args);
     }, wait);
   };
 }
--- a/src/debounce.test.ts
+++ b/src/debounce.test.ts
@@ -12,3 +12,14 @@ describe('debounce', () => {
     expect(spy).toHaveBeenCalledTimes(1);
   });
+
+  it('uses the latest arguments for the trailing call', () => {
+    jest.useFakeTimers();
+    const spy = jest.fn();
+    const d = debounce(spy, 100);
+    d(1);
+    d(2);
+    d(3);
+    jest.advanceTimersByTime(100);
+    expect(spy).toHaveBeenCalledWith(3);
+  });
 });

